import{_ as a,c as o,o as r,aj as d}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: BlobManager","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/BlobManager.md","filePath":"reference/js-bao-wss-client/api/interfaces/BlobManager.md"}'),t={name:"reference/js-bao-wss-client/api/interfaces/BlobManager.md"};function n(l,e,s,c,i,h){return r(),o("div",null,[...e[0]||(e[0]=[d('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / BlobManager</p><h1 id="interface-blobmanager" tabindex="-1">Interface: BlobManager <a class="header-anchor" href="#interface-blobmanager" aria-label="Permalink to “Interface: BlobManager”">​</a></h1><p>Manages file attachments (blobs) for documents: uploads with a persistent background retry queue, a local cache for reads and offline access, and download URL generation. Most apps use the per-document view returned by <code>forDocument()</code> (exposed as <code>client.document(id).blobs()</code>) rather than calling these methods directly.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="closeidb" tabindex="-1">closeIdb() <a class="header-anchor" href="#closeidb" aria-label="Permalink to “closeIdb()”">​</a></h3><blockquote><p><strong>closeIdb</strong>(): <code>void</code></p></blockquote><p>Close the IDB connection without resetting state. Called on pagehide to release the connection before the page unloads.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="configureidentity" tabindex="-1">configureIdentity() <a class="header-anchor" href="#configureidentity" aria-label="Permalink to “configureIdentity()”">​</a></h3><blockquote><p><strong>configureIdentity</strong>(<code>appId</code>, <code>userId</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Configure the BlobManager for the active user context.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="appid" tabindex="-1">appId <a class="header-anchor" href="#appid" aria-label="Permalink to “appId”">​</a></h5><p><code>string</code></p><h5 id="userid" tabindex="-1">userId <a class="header-anchor" href="#userid" aria-label="Permalink to “userId”">​</a></h5><p><code>string</code> | <code>null</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="delete" tabindex="-1">delete() <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>documentId</code>, <code>blobId</code>): <code>Promise</code>&lt;{ <code>deleted</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Deletes a blob from a document. Any queued upload for the same blob is cancelled and its locally cached bytes are removed before the server delete is issued.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="blobid" tabindex="-1">blobId <a class="header-anchor" href="#blobid" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>deleted</code>: <code>boolean</code>; }&gt;</p><hr><h3 id="fordocument" tabindex="-1">forDocument() <a class="header-anchor" href="#fordocument" aria-label="Permalink to “forDocument()”">​</a></h3><blockquote><p><strong>forDocument</strong>(<code>documentId</code>): <a href="./DocumentBlobContext.html"><code>DocumentBlobContext</code></a></p></blockquote><p>Returns a <code>DocumentBlobContext</code> with every blob operation bound to the given document — the recommended way to work with blobs, exposed as <code>client.document(id).blobs()</code>.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-1" tabindex="-1">documentId <a class="header-anchor" href="#documentid-1" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./DocumentBlobContext.html"><code>DocumentBlobContext</code></a></p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>&lt;<code>T</code>&gt;(<code>documentId</code>, <code>blobId</code>): <code>Promise</code>&lt;<code>T</code>&gt;</p></blockquote><p>Fetches the server-side metadata record for a single blob (filename, content type, size, and related fields) without downloading its content.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to “T”">​</a></h5><p><code>T</code> = <code>unknown</code></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-2" tabindex="-1">documentId <a class="header-anchor" href="#documentid-2" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="blobid-1" tabindex="-1">blobId <a class="header-anchor" href="#blobid-1" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>T</code>&gt;</p><hr><h3 id="getdownloadurl" tabindex="-1">getDownloadUrl() <a class="header-anchor" href="#getdownloadurl" aria-label="Permalink to “getDownloadUrl()”">​</a></h3><blockquote><p><strong>getDownloadUrl</strong>(<code>documentId</code>, <code>blobId</code>, <code>params?</code>): <code>string</code></p></blockquote><p>Builds the download URL for a blob on the API host, optionally forcing a disposition or suggesting an attachment filename. The URL itself carries no credentials — requests to it must still be authenticated (e.g. via a service worker attaching the token).</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-3" tabindex="-1">documentId <a class="header-anchor" href="#documentid-3" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="blobid-2" tabindex="-1">blobId <a class="header-anchor" href="#blobid-2" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><h5 id="params" tabindex="-1">params? <a class="header-anchor" href="#params" aria-label="Permalink to “params?”">​</a></h5><p><a href="./BlobDownloadUrlParams.html"><code>BlobDownloadUrlParams</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getuploadconcurrency" tabindex="-1">getUploadConcurrency() <a class="header-anchor" href="#getuploadconcurrency" aria-label="Permalink to “getUploadConcurrency()”">​</a></h3><blockquote><p><strong>getUploadConcurrency</strong>(): <code>number</code></p></blockquote><p>Returns the current limit on parallel background uploads (default 2).</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getuploads" tabindex="-1">getUploads() <a class="header-anchor" href="#getuploads" aria-label="Permalink to “getUploads()”">​</a></h3><blockquote><p><strong>getUploads</strong>(<code>documentId?</code>): <a href="./BlobUploadStatus.html"><code>BlobUploadStatus</code></a>[]</p></blockquote><p>Returns a snapshot of the background upload queue — optionally filtered to one document — sorted with the most recently updated entries first.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-4" tabindex="-1">documentId? <a class="header-anchor" href="#documentid-4" aria-label="Permalink to “documentId?”">​</a></h5><p><code>string</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./BlobUploadStatus.html"><code>BlobUploadStatus</code></a>[]</p><hr><h3 id="handlenetworkmode" tabindex="-1">handleNetworkMode() <a class="header-anchor" href="#handlenetworkmode" aria-label="Permalink to “handleNetworkMode()”">​</a></h3><blockquote><p><strong>handleNetworkMode</strong>(<code>mode</code>): <code>void</code></p></blockquote><p>Applies a network mode change to the upload queue: going online (or auto) resumes background upload processing, going offline stops it. Queued uploads are kept and retried once the network is available again.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mode" tabindex="-1">mode <a class="header-anchor" href="#mode" aria-label="Permalink to “mode”">​</a></h5><p><a href="./../type-aliases/NetworkMode.html"><code>NetworkMode</code></a></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>&lt;<code>T</code>&gt;(<code>documentId</code>, <code>params?</code>): <code>Promise</code>&lt;<a href="./BlobListResult.html"><code>BlobListResult</code></a>&lt;<code>T</code>&gt;&gt;</p></blockquote><p>Lists the blobs attached to a document, one page at a time. Pass the previous page&#39;s <code>nextCursor</code> as <code>params.cursor</code> to fetch the next page.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="t-1" tabindex="-1">T <a class="header-anchor" href="#t-1" aria-label="Permalink to “T”">​</a></h5><p><code>T</code> = <code>unknown</code></p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-5" tabindex="-1">documentId <a class="header-anchor" href="#documentid-5" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="params-1" tabindex="-1">params? <a class="header-anchor" href="#params-1" aria-label="Permalink to “params?”">​</a></h5><p><a href="./BlobListParams.html"><code>BlobListParams</code></a></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./BlobListResult.html"><code>BlobListResult</code></a>&lt;<code>T</code>&gt;&gt;</p><hr><h3 id="pausealluploads" tabindex="-1">pauseAllUploads() <a class="header-anchor" href="#pausealluploads" aria-label="Permalink to “pauseAllUploads()”">​</a></h3><blockquote><p><strong>pauseAllUploads</strong>(<code>documentId?</code>): <code>void</code></p></blockquote><p>Pauses every queued or in-progress upload, or only those for one document when <code>documentId</code> is given.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-6" tabindex="-1">documentId? <a class="header-anchor" href="#documentid-6" aria-label="Permalink to “documentId?”">​</a></h5><p><code>string</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="pauseupload" tabindex="-1">pauseUpload() <a class="header-anchor" href="#pauseupload" aria-label="Permalink to “pauseUpload()”">​</a></h3><blockquote><p><strong>pauseUpload</strong>(<code>queueId</code>, <code>documentId?</code>): <code>boolean</code></p></blockquote><p>Pauses a queued or in-progress upload, aborting any in-flight transfer. Pass <code>documentId</code> to guard against pausing an upload that belongs to a different document. Returns false when the upload is unknown, belongs to another document, or is already paused or finished.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="queueid" tabindex="-1">queueId <a class="header-anchor" href="#queueid" aria-label="Permalink to “queueId”">​</a></h5><p><code>string</code></p><h5 id="documentid-7" tabindex="-1">documentId? <a class="header-anchor" href="#documentid-7" aria-label="Permalink to “documentId?”">​</a></h5><p><code>string</code></p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="prefetch" tabindex="-1">prefetch() <a class="header-anchor" href="#prefetch" aria-label="Permalink to “prefetch()”">​</a></h3><blockquote><p><strong>prefetch</strong>(<code>documentId</code>, <code>blobIds</code>, <code>options?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Downloads a set of blobs into the local cache ahead of time (e.g. before going offline), running up to <code>concurrency</code> downloads in parallel (default 2). Individual failures are logged and skipped, so the returned promise resolves even when some blobs could not be fetched.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-8" tabindex="-1">documentId <a class="header-anchor" href="#documentid-8" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="blobids" tabindex="-1">blobIds <a class="header-anchor" href="#blobids" aria-label="Permalink to “blobIds”">​</a></h5><p><code>string</code>[]</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./BlobPrefetchOptions.html"><code>BlobPrefetchOptions</code></a></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="read" tabindex="-1">read() <a class="header-anchor" href="#read" aria-label="Permalink to “read()”">​</a></h3><blockquote><p><strong>read</strong>(<code>documentId</code>, <code>blobId</code>, <code>options?</code>): <code>Promise</code>&lt;<code>string</code> | <code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>Blob</code>&gt;</p></blockquote><p>Reads a blob&#39;s content, preferring the local cache: cached bytes are returned without a network round trip unless <code>forceRedownload</code> is set. On a cache miss the blob is downloaded from the server and cached for next time. Throws when the client is offline and no cached copy exists. The <code>as</code> option selects the return format (default <code>Uint8Array</code>).</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-9" tabindex="-1">documentId <a class="header-anchor" href="#documentid-9" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="blobid-3" tabindex="-1">blobId <a class="header-anchor" href="#blobid-3" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./BlobReadOptions.html"><code>BlobReadOptions</code></a></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code> | <code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>Blob</code>&gt;</p><hr><h3 id="reset" tabindex="-1">reset() <a class="header-anchor" href="#reset" aria-label="Permalink to “reset()”">​</a></h3><blockquote><p><strong>reset</strong>(): <code>void</code></p></blockquote><p>Clears all in-memory blob state — the upload queue, cached bytes, and the active user identity. Called when the user signs out; queued uploads persisted locally are restored the next time an identity is configured.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="resumealluploads" tabindex="-1">resumeAllUploads() <a class="header-anchor" href="#resumealluploads" aria-label="Permalink to “resumeAllUploads()”">​</a></h3><blockquote><p><strong>resumeAllUploads</strong>(<code>documentId?</code>): <code>void</code></p></blockquote><p>Resumes every paused upload, or only those for one document when <code>documentId</code> is given, and restarts queue processing if anything was resumed.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-10" tabindex="-1">documentId? <a class="header-anchor" href="#documentid-10" aria-label="Permalink to “documentId?”">​</a></h5><p><code>string</code></p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="resumeupload" tabindex="-1">resumeUpload() <a class="header-anchor" href="#resumeupload" aria-label="Permalink to “resumeUpload()”">​</a></h3><blockquote><p><strong>resumeUpload</strong>(<code>queueId</code>, <code>documentId?</code>): <code>boolean</code></p></blockquote><p>Resumes a paused upload, marking it eligible for an immediate retry. Returns false when the upload is unknown, belongs to another document, or is not currently paused.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="queueid-1" tabindex="-1">queueId <a class="header-anchor" href="#queueid-1" aria-label="Permalink to “queueId”">​</a></h5><p><code>string</code></p><h5 id="documentid-11" tabindex="-1">documentId? <a class="header-anchor" href="#documentid-11" aria-label="Permalink to “documentId?”">​</a></h5><p><code>string</code></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="setuploadconcurrency" tabindex="-1">setUploadConcurrency() <a class="header-anchor" href="#setuploadconcurrency" aria-label="Permalink to “setUploadConcurrency()”">​</a></h3><blockquote><p><strong>setUploadConcurrency</strong>(<code>value</code>): <code>void</code></p></blockquote><p>Sets how many background uploads may run in parallel. Values are rounded down and clamped to at least 1; raising the limit kicks off queue processing immediately.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="value" tabindex="-1">value <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h5><p><code>number</code></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="uploadfromsource" tabindex="-1">uploadFromSource() <a class="header-anchor" href="#uploadfromsource" aria-label="Permalink to “uploadFromSource()”">​</a></h3><blockquote><p><strong>uploadFromSource</strong>(<code>documentId</code>, <code>source</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./BlobUploadResult.html"><code>BlobUploadResult</code></a>&gt;</p></blockquote><p>Uploads a file or binary source to a document. Fills in the filename and content type from the source when possible, computes the SHA-256 hash, and assigns a new blob ID. When a user is signed in the blob is stored locally and one immediate upload attempt is made; if that attempt fails with a retryable error the upload stays queued for background retry and the result reports <code>bytesTransferred: 0</code>. Non-retryable failures (e.g. permission errors) reject.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-12" tabindex="-1">documentId <a class="header-anchor" href="#documentid-12" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><h5 id="source" tabindex="-1">source <a class="header-anchor" href="#source" aria-label="Permalink to “source”">​</a></h5><p><code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>File</code> | <code>Blob</code></p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><a href="./BlobUploadSourceOptions.html"><code>BlobUploadSourceOptions</code></a></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./BlobUploadResult.html"><code>BlobUploadResult</code></a>&gt;</p><hr><h3 id="uploadimmediate" tabindex="-1">uploadImmediate() <a class="header-anchor" href="#uploadimmediate" aria-label="Permalink to “uploadImmediate()”">​</a></h3><blockquote><p><strong>uploadImmediate</strong>(<code>request</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./BlobUploadResult.html"><code>BlobUploadResult</code></a>&gt;</p></blockquote><p>Uploads a blob to the server in a single request, bypassing the background queue entirely — no local persistence and no retry on failure. Rejects on any network failure or non-2xx response (the error carries the HTTP <code>status</code>). <code>uploadFromSource</code> uses this internally; prefer that method unless you need direct, one-shot semantics.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="request" tabindex="-1">request <a class="header-anchor" href="#request" aria-label="Permalink to “request”">​</a></h5><p><a href="./BlobUploadRequest.html"><code>BlobUploadRequest</code></a></p><h5 id="options-3" tabindex="-1">options? <a class="header-anchor" href="#options-3" aria-label="Permalink to “options?”">​</a></h5><h6 id="signal" tabindex="-1">signal? <a class="header-anchor" href="#signal" aria-label="Permalink to “signal?”">​</a></h6><p><code>AbortSignal</code></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./BlobUploadResult.html"><code>BlobUploadResult</code></a>&gt;</p>',213)])])}const b=a(t,[["render",n]]);export{p as __pageData,b as default};
